# Kaggle kernel: runs a list of training jobs, one worker per GPU. Generated by experiments/make_kernel.py.
import json
import os
import subprocess
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

SOURCES = {}  # filled in by make_kernel.py: relative path -> file content
JOBS = []  # filled in by make_kernel.py: list of {"name": ..., "args": [...]}
TRAIN_SHARDS = 0  # filled in by make_kernel.py
DEADLINE_SECONDS = 0  # filled in by make_kernel.py: no job starts after this

START = time.time()
SRC = Path("/tmp/src")
DATA = Path("/tmp/data")
OUT = Path("/kaggle/working")


def sh(cmd: str) -> str:
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    return result.stdout + result.stderr


print(sh("nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv"), flush=True)
print(sh(f"{sys.executable} -c 'import torch, triton; print(torch.__version__, triton.__version__)'"), flush=True)

for rel, content in SOURCES.items():
    path = SRC / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)

sys.path.insert(0, str(SRC))
from mhc_lab.data import REPO_URL  # noqa: E402

import urllib.request  # noqa: E402

DATA.mkdir(parents=True, exist_ok=True)
names = [f"train_{i:05d}.npy" for i in range(TRAIN_SHARDS)] + ["validation_00000.npy"]


def fetch(name: str) -> None:
    for attempt in range(5):
        try:
            partial = DATA / (name + ".part")
            urllib.request.urlretrieve(f"{REPO_URL}/{name}", partial)
            partial.rename(DATA / name)
            return
        except Exception as error:  # retry transient network errors
            print(f"retry {name}: {error}", flush=True)
            time.sleep(5 * (attempt + 1))
    raise RuntimeError(f"could not download {name}")


with ThreadPoolExecutor(8) as pool:
    list(pool.map(fetch, names))
print(f"downloaded {len(names)} shards in {time.time() - START:.0f}s", flush=True)

gpus = int(sh("nvidia-smi -L | wc -l").strip() or 0)
print(f"{gpus} GPUs, {len(JOBS)} jobs", flush=True)
queue = list(JOBS)
lock = threading.Lock()
status = {}


def worker(gpu: int) -> None:
    while True:
        with lock:
            if not queue:
                return
            if time.time() - START > DEADLINE_SECONDS:
                for job in queue:
                    status[job["name"]] = "skipped (deadline)"
                queue.clear()
                return
            job = queue.pop(0)
        began = time.time()
        run_dir = OUT / "runs" / job["name"]
        run_dir.mkdir(parents=True, exist_ok=True)
        module = job.get("module", "mhc_lab.train")
        cmd = [sys.executable, "-m", module, "--out", str(run_dir), "--data-dir", str(DATA), *job["args"]]
        env = {**os.environ, "CUDA_VISIBLE_DEVICES": str(gpu), "PYTHONPATH": str(SRC)}
        with open(run_dir / "log.txt", "w") as log:
            code = subprocess.run(cmd, env=env, stdout=log, stderr=subprocess.STDOUT).returncode
        took = time.time() - began
        with lock:
            status[job["name"]] = f"exit {code} in {took:.0f}s on gpu {gpu}"
            print(f"[{time.time() - START:.0f}s] {job['name']}: {status[job['name']]}", flush=True)
            (OUT / "status.json").write_text(json.dumps(status, indent=1))


threads = [threading.Thread(target=worker, args=(g,)) for g in range(max(gpus, 1))]
for t in threads:
    t.start()
for t in threads:
    t.join()
(OUT / "status.json").write_text(json.dumps(status, indent=1))
print(f"all done in {time.time() - START:.0f}s", flush=True)
